theorem even_integral_preserved {ε : ℝ} (hε : |ε|≤1) {f : ℝ → ℝ}
    (hf : Integrable f γ) (he : ∀ c, f (-c)=f c) :
    (∫ c, f c ∂law ε) = ∫ c, f c ∂γ

theorem observed_set_symmetric {β : Type*} [MeasurableSpace β] {f : ℝ → β}
    (he : ∀ c, f (-c)=f c) {s : Set ℝ} (hs : MeasurableSet[observedSpace f] s)
    (c : ℝ) : -c∈s ↔ c∈s

theorem weak_integral_zero {f : GaussianL2} {g : GaussianVectorL2}
    (hf : (f,g) ∈ closedCylindricalDerivative.graph) :
    (∫ ω, inner ℝ (g ω) (field ω) ∂gaussianProduct)=0
